// 1. Retrieve the original chat request
const chat = $('When Chat Message Received').first().json;

const sessionId = String(chat.sessionId ?? '').trim();

const confirmed =
  String(chat.chatInput ?? '')
    .trim()
    .toUpperCase() === 'CONFIRM SUPPORT TICKET';

// 2. Retrieve pending ticket records
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id != null);

// 3. Standard rejection response
function reject(status, message) {
  return [{
    json: {
      success: false,
      pending_valid: false,
      status,
      ticket_id: '',
      session_id: sessionId,
      output: message
    }
  }];
}

// 4. Verify explicit confirmation
if (!sessionId || !confirmed) {
  return reject(
    'CONFIRMATION_REQUIRED',
    'A valid session and explicit confirmation are required.'
  );
}

// 5. Verify pending ticket existence
if (rows.length === 0) {
  return reject(
    'PENDING_NOT_FOUND',
    'There is no pending support ticket to confirm. Please request a new ticket preview.'
  );
}

// 6. Prevent ambiguous records
if (rows.length !== 1) {
  return reject(
    'AMBIGUOUS_PENDING_TICKET',
    'Multiple pending requests were found. Please contact customer support.'
  );
}

const pending = rows[0];

if (!String(pending.request_id ?? '').trim()) {
  return reject(
    'INVALID_PREVIEW_VERSION',
    'The ticket preview version is missing. Please request a new ticket preview.'
  );
}

// 7. Verify session binding
if (pending.session_id !== sessionId) {
  return reject(
    'SESSION_MISMATCH',
    'The pending request does not belong to this session.'
  );
}

// 8. Verify authorization status

if (pending.status === 'PREPARED') {
  return reject(
    'PREVIEW_NOT_ACTIVATED',
    'The ticket preview is not ready for confirmation. Please request a new preview.'
  );
}

if (pending.status === 'CONSUMED') {
  return reject(
    'CONFIRMATION_ALREADY_USED',
    'This request has already been processed. No additional ticket has been created.'
  );
}

if (pending.status === 'PROCESSING') {
  return reject(
    'TICKET_PROCESSING',
    'Your request is already being processed or awaiting review. Please do not submit it again.'
  );
}

if (pending.status === 'EXPIRED') {
  return reject(
    'CONFIRMATION_EXPIRED',
    'Your confirmation has expired. Please request a new ticket preview.'
  );
}

if (pending.status !== 'PENDING') {
  return reject(
    'INVALID_PENDING_STATUS',
    'This request is no longer available for confirmation.'
  );
}

// 9. Verify expiration
const expiresAt = Date.parse(pending.expires_at ?? '');

if (!Number.isFinite(expiresAt)) {
  return reject(
    'INVALID_PENDING_TICKET',
    'The pending request is invalid. Please request a new ticket preview.'
  );
}

if (Date.now() >= expiresAt) {
  return reject(
    'CONFIRMATION_EXPIRED',
    'Your confirmation has expired. Please request a new ticket preview.'
  );
}

// 10. Return stored business parameters
return [{
  json: {
    success: true,
    pending_valid: true,
    status: 'PENDING_VALIDATED',

    pending_ticket_id: pending.id,
    session_id: sessionId,
    request_id: String(pending.request_id),

    customer_email: pending.customer_email,
    order_id: pending.order_id || '',
    issue_type: pending.issue_type,
    issue_summary: pending.issue_summary,

    customer_confirmed: true
  }
}];

// 1. Retrieve workflow results
const rows = $input.all().map(item => item.json);

// 2. Standard chat response
function respond(output) {
  return [{
    json: { output }
  }];
}

// 3. Handle technical errors or unexpected results
if (
  rows.length !== 1 ||
  rows[0].error
) {
  return respond(
    'We could not verify the final status of your support request. Please do not submit it again immediately, as a ticket may already have been created.'
  );
}

const result = rows[0];

const ticketId = String(result.ticket_id ?? '').trim();
const status = result.status;
const notificationStatus = result.notification_status;

// 4. Handle successful business results
if (
  result.success === true &&
  ticketId &&
  ['CREATED', 'ALREADY_EXISTS'].includes(status)
) {
  const lines = [];

  if (status === 'CREATED') {
    lines.push('## ✅ Support Ticket Created');
    lines.push('');
    lines.push('Your support request has been successfully recorded.');
  } else {
    lines.push('## 📋 Existing Support Ticket');
    lines.push('');
    lines.push('An existing open ticket matches your request. No duplicate ticket has been created.');
  }

  lines.push('');
  lines.push(`- **Ticket ID:** ${ticketId}`);
  lines.push('- **Ticket status:** OPEN');

  if (notificationStatus === 'SENT') {
    lines.push('- **Support notification:** Sent');
    lines.push('');
    lines.push('Your request is available for review by our support team.');
  } else if (notificationStatus === 'FAILED') {
    lines.push('- **Support notification:** Not sent');
    lines.push('');
    lines.push('Your ticket has been recorded, but the automatic notification could not be sent. Please retain your ticket ID for follow-up.');
  } else {
    lines.push('- **Support notification:** Not confirmed');
  }

  lines.push('');
  lines.push('Please keep your ticket ID for future reference.');

  return respond(lines.join('\n'));
}

// 5. Handle known authorization failures
const messages = {
  VALIDATION_FAILED:
    'The support request contains invalid information. Please request a new ticket preview.',

  CONFIRMATION_REQUIRED:
    'Explicit confirmation is required before creating a support ticket.',

  PENDING_NOT_FOUND:
    'No pending support ticket was found. Please request a new ticket preview.',

  CONFIRMATION_EXPIRED:
    'Your confirmation has expired. Please request a new ticket preview.',

  CONFIRMATION_ALREADY_USED:
    'This confirmation has already been used. No additional ticket has been created.',

  TICKET_PROCESSING:
    'Your request is already being processed or awaiting review. Please do not submit it again.',

  AMBIGUOUS_PENDING_TICKET:
    'Multiple pending requests were found. Please contact customer support.',

  SESSION_MISMATCH:
    'The pending request does not belong to this session.',

  INVALID_PENDING_STATUS:
    'This request is no longer available for confirmation.',

  INVALID_PENDING_TICKET:
    'The stored request is invalid. Please request a new ticket preview.'
};

if (
  result.success === false &&
  Object.prototype.hasOwnProperty.call(messages, status)
) {
  return respond(messages[status]);
}

// 6. Handle unverified execution outcomes
return respond(
  'We could not verify the final status of your support request. Please contact customer support before submitting another request.'
);

// 1. Retrieve the activation result
const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id != null);

// 2. Retrieve the original prepared preview
const prepared =
  $('Load Prepared Ticket Preview').first().json;

// 3. Verify successful activation
if (
  rows.length !== 1 ||
  rows[0].status !== 'PENDING' ||
  String(rows[0].id) !== String(prepared.id) ||
  rows[0].session_id !== prepared.session_id ||
  rows[0].request_id !== prepared.request_id ||
  !String(rows[0].preview_markdown ?? '').trim()
) {
  return [{
    json: {
      output: 'Unable to prepare your support ticket preview. Please request a new preview.'
    }
  }];
}

// 4. Return the stored Markdown preview
return [{
  json: {
    output: rows[0].preview_markdown
  }
}];
